
#include "mml_event_vm_v2.h"
void mml_event_vm_init(MMLEventVM*v,const MMLEventInstr*c,size_t n){if(v){v->code=c;v->count=n;v->pc=0;v->halted=false;v->blocked=false;v->steps=0;}}
bool mml_event_vm_step(MMLEventVM*v,MMLWorld*w){if(!v||!w||v->halted||v->pc>=v->count)return false;const MMLEventInstr*i=&v->code[v->pc];v->blocked=false;switch(i->op){case MML_EVT_END:v->halted=true;v->pc++;break;case MML_EVT_SET_FLAG:if(!mml_world_set_flag(w,(uint16_t)i->a,true))return false;v->pc++;break;case MML_EVT_CLEAR_FLAG:if(!mml_world_set_flag(w,(uint16_t)i->a,false))return false;v->pc++;break;case MML_EVT_WAIT_FLAG:if(!mml_world_get_flag(w,(uint16_t)i->a)){v->blocked=true;return true;}v->pc++;break;case MML_EVT_MESSAGE:if(!mml_world_queue_message(w,i->a))return false;v->pc++;break;case MML_EVT_OBJECT_STATE:{MMLWorldObject*o=mml_world_find(w,i->a);if(!o)return false;o->state=(uint16_t)i->b;v->pc++;break;}case MML_EVT_OBJECT_ACTIVE:{MMLWorldObject*o=mml_world_find(w,i->a);if(!o)return false;o->active=i->b!=0;v->pc++;break;}case MML_EVT_TRANSITION_AREA:if(!mml_world_request_transition(w,MML_TRANSITION_AREA_ONLY,i->payload))return false;v->pc++;break;case MML_EVT_TRANSITION_STAGE:if(!mml_world_request_transition(w,MML_TRANSITION_FULL_STAGE,i->payload))return false;v->pc++;break;default:return false;}v->steps++;return true;}
bool mml_event_vm_run(MMLEventVM*v,MMLWorld*w,uint32_t max){if(!v||!w)return false;uint32_t n=0;while(!v->halted&&!v->blocked&&n<max){if(!mml_event_vm_step(v,w))return false;n++;}return true;}
